  <script>
    // Reference data for 15 districts in Nan province
    const DISTRICTS = [
      { id: '1', name: 'เมืองน่าน' },
      { id: '2', name: 'แม่จริม' },
      { id: '3', name: 'บ้านหลวง' },
      { id: '4', name: 'นาน้อย' },
      { id: '5', name: 'ปัว' },
      { id: '6', name: 'ท่าวังผา' },
      { id: '7', name: 'เวียงสา' },
      { id: '8', name: 'ทุ่งช้าง' },
      { id: '9', name: 'เชียงกลาง' },
      { id: '10', name: 'นาหมื่น' },
      { id: '11', name: 'สันติสุข' },
      { id: '12', name: 'บ่อเกลือ' },
      { id: '13', name: 'สองแคว' },
      { id: '14', name: 'ภูเพียง' },
      { id: '15', name: 'เฉลิมพระเกียรติ' }
    ];

    let allRecords = [];
    let districtChart = null;
    let monthlyChart = null;

    const defaultConfig = {
      main_title: 'ระบบติดตามผลการดำเนินงาน',
      subtitle: 'จปฐ. ปี 2569 และประเด็น 5+1 จังหวัดน่าน',
      dashboard_title: 'ภาพรวมการรายงาน',
      districts_title: 'ข้อมูลรายอำเภอ',
      database_title: 'ฐานข้อมูล',
      jpth_form_url: 'https://forms.gle/EdmYLuoSgmjvn6Wm8',
      issue_form_url: 'https://forms.gle/ijAuVg8Exb7x1u7UA',
      primary_color: '#667eea',
      secondary_color: '#06b6d4',
      accent_color: '#a855f7',
      success_color: '#10b981',
      text_color: '#1e293b',
      font_family: 'Sarabun',
      font_size: 16
    };

    // Navigation
    function showPage(pageId) {
      const pages = document.querySelectorAll('.page');
      const buttons = document.querySelectorAll('.nav-button');

      pages.forEach(page => page.classList.remove('active'));
      buttons.forEach(btn => btn.classList.remove('active'));

      document.getElementById(`${pageId}-page`).classList.add('active');
      event.target.classList.add('active');
    }

    // Get unique months from records
    function getUniqueMonths() {
      const months = new Set();
      allRecords.forEach(record => {
        if (record.month) months.add(record.month);
      });
      return Array.from(months).sort();
    }

    // Update filter dropdowns
    function updateFilterDropdowns() {
      const months = getUniqueMonths();

      // Update all month filters
      const monthFilters = ['month-filter', 'districts-month-filter', 'db-month-filter'];
      monthFilters.forEach(filterId => {
        const select = document.getElementById(filterId);
        const currentValue = select.value;
        select.innerHTML = '<option value="all">ทุกเดือน</option>';
        months.forEach(month => {
          const option = document.createElement('option');
          option.value = month;
          option.textContent = month;
          select.appendChild(option);
        });
        select.value = currentValue;
      });

      // Update district filters
      const districtFilters = ['district-filter', 'db-district-filter'];
      districtFilters.forEach(filterId => {
        const select = document.getElementById(filterId);
        const currentValue = select.value;
        select.innerHTML = '<option value="all">ทุกอำเภอ</option>';
        DISTRICTS.forEach(district => {
          const option = document.createElement('option');
          option.value = district.id;
          option.textContent = district.name;
          select.appendChild(option);
        });
        select.value = currentValue;
      });
    }

    // Get filtered records
    function getFilteredRecords(monthFilter = 'all', districtFilter = 'all') {
      let filtered = allRecords;

      if (monthFilter !== 'all') {
        filtered = filtered.filter(r => r.month === monthFilter);
      }

      if (districtFilter !== 'all') {
        filtered = filtered.filter(r => r.district_id === districtFilter);
      }

      return filtered;
    }

    // Calculate rating based on criteria
    function calculateRating(jpthStatus, jpthOntime, issueStatus, issueOntime) {
      const jpthReported = jpthStatus === 'reported';
      const issueReported = issueStatus === 'reported';

      if (jpthReported && issueReported && jpthOntime && issueOntime) {
        return 'A';
      } else if ((jpthReported && jpthOntime) || (issueReported && issueOntime)) {
        return 'B';
      } else if (jpthReported && issueReported) {
        return 'C';
      } else {
        return 'D';
      }
    }

    // Check if report is on time (within current month)
    function isOnTime(timestamp) {
      if (!timestamp) return false;
      const reportDate = new Date(timestamp);
      const now = new Date();
      return reportDate.getMonth() === now.getMonth() && 
             reportDate.getFullYear() === now.getFullYear();
    }

    // Get district data with rating
    function getDistrictData(districtId, records = allRecords) {
      const districtRecords = records.filter(r => r.district_id === districtId);
      if (districtRecords.length === 0) {
        return {
          jpth_status: 'not_reported',
          jpth_ontime: false,
          issue_status: 'not_reported',
          issue_ontime: false,
          rating: 'D'
        };
      }

      const latest = districtRecords[districtRecords.length - 1];
      const jpthOntime = isOnTime(latest.jpth_timestamp);
      const issueOntime = isOnTime(latest.issue_5plus1_timestamp);
      const rating = calculateRating(
        latest.jpth_status,
        jpthOntime,
        latest.issue_5plus1_status,
        issueOntime
      );

      return {
        jpth_status: latest.jpth_status,
        jpth_timestamp: latest.jpth_timestamp,
        jpth_ontime: jpthOntime,
        issue_status: latest.issue_5plus1_status,
        issue_timestamp: latest.issue_5plus1_timestamp,
        issue_ontime: issueOntime,
        rating: rating,
        month: latest.month
      };
    }

    // Apply filters and update dashboard
    function applyFilters() {
      const monthFilter = document.getElementById('month-filter').value;
      const districtFilter = document.getElementById('district-filter').value;

      const filteredRecords = getFilteredRecords(monthFilter, districtFilter);
      updateDashboard(filteredRecords, monthFilter, districtFilter);
    }

    // Update summary cards
    function updateSummaryCards(records, districtFilter) {
      let jpthCount = 0;
      let issueCount = 0;
      let ontimeCount = 0;
      const ratingCounts = { A: 0, B: 0, C: 0, D: 0 };

      const districtsToCheck = districtFilter === 'all' ? DISTRICTS : DISTRICTS.filter(d => d.id === districtFilter);

      districtsToCheck.forEach(district => {
        const data = getDistrictData(district.id, records);
        if (data.jpth_status === 'reported') jpthCount++;
        if (data.issue_status === 'reported') issueCount++;
        if (data.jpth_ontime && data.issue_ontime && 
            data.jpth_status === 'reported' && data.issue_status === 'reported') {
          ontimeCount++;
        }
        ratingCounts[data.rating]++;
      });

      const totalDistricts = districtsToCheck.length;

      document.getElementById('jpth-reported').textContent = jpthCount;
      document.getElementById('issue-reported').textContent = issueCount;
      const ontimeRate = totalDistricts > 0 ? Math.round((ontimeCount / totalDistricts) * 100) : 0;
      document.getElementById('ontime-rate').textContent = `${ontimeRate}%`;

      document.getElementById('rating-a-count').textContent = `${ratingCounts.A} อำเภอ`;
      document.getElementById('rating-b-count').textContent = `${ratingCounts.B} อำเภอ`;
      document.getElementById('rating-c-count').textContent = `${ratingCounts.C} อำเภอ`;
      document.getElementById('rating-d-count').textContent = `${ratingCounts.D} อำเภอ`;
    }

    // Update district chart
    function updateDistrictChart(records, districtFilter) {
      const ctx = document.getElementById('districtChart').getContext('2d');

      const districtsToShow = districtFilter === 'all' ? DISTRICTS : DISTRICTS.filter(d => d.id === districtFilter);

      const labels = districtsToShow.map(d => d.name);
      const jpthData = districtsToShow.map(d => {
        const data = getDistrictData(d.id, records);
        return data.jpth_status === 'reported' ? 1 : 0;
      });
      const issueData = districtsToShow.map(d => {
        const data = getDistrictData(d.id, records);
        return data.issue_status === 'reported' ? 1 : 0;
      });

      if (districtChart) {
        districtChart.destroy();
      }

      districtChart = new Chart(ctx, {
        type: 'bar',
        data: {
          labels: labels,
          datasets: [
            {
              label: 'รายงาน จปฐ.',
              data: jpthData,
              backgroundColor: 'rgba(102, 126, 234, 0.8)',
              borderColor: 'rgba(102, 126, 234, 1)',
              borderWidth: 2,
              borderRadius: 6
            },
            {
              label: 'รายงาน 5+1',
              data: issueData,
              backgroundColor: 'rgba(6, 182, 212, 0.8)',
              borderColor: 'rgba(6, 182, 212, 1)',
              borderWidth: 2,
              borderRadius: 6
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          scales: {
            y: {
              beginAtZero: true,
              max: 1,
              ticks: {
                stepSize: 1,
                callback: function(value) {
                  return value === 1 ? 'รายงานแล้ว' : 'ยังไม่รายงาน';
                }
              }
            }
          },
          plugins: {
            legend: {
              display: true,
              position: 'top'
            }
          }
        }
      });
    }

    // Update monthly chart
    function updateMonthlyChart(records) {
      const ctx = document.getElementById('monthlyChart').getContext('2d');

      // Group by month
      const monthlyData = {};
      records.forEach(record => {
        const month = record.month || 'ไม่ระบุ';
        if (!monthlyData[month]) {
          monthlyData[month] = { jpth: 0, issue: 0 };
        }
        if (record.jpth_status === 'reported') monthlyData[month].jpth++;
        if (record.issue_5plus1_status === 'reported') monthlyData[month].issue++;
      });

      const months = Object.keys(monthlyData).sort();
      const jpthCounts = months.map(m => monthlyData[m].jpth);
      const issueCounts = months.map(m => monthlyData[m].issue);

      if (monthlyChart) {
        monthlyChart.destroy();
      }

      monthlyChart = new Chart(ctx, {
        type: 'line',
        data: {
          labels: months.length > 0 ? months : ['ยังไม่มีข้อมูล'],
          datasets: [
            {
              label: 'รายงาน จปฐ.',
              data: jpthCounts.length > 0 ? jpthCounts : [0],
              borderColor: 'rgba(102, 126, 234, 1)',
              backgroundColor: 'rgba(102, 126, 234, 0.1)',
              borderWidth: 3,
              tension: 0.4,
              fill: true
            },
            {
              label: 'รายงาน 5+1',
              data: issueCounts.length > 0 ? issueCounts : [0],
              borderColor: 'rgba(6, 182, 212, 1)',
              backgroundColor: 'rgba(6, 182, 212, 0.1)',
              borderWidth: 3,
              tension: 0.4,
              fill: true
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          scales: {
            y: {
              beginAtZero: true,
              ticks: {
                stepSize: 1
              }
            }
          },
          plugins: {
            legend: {
              display: true,
              position: 'top'
            }
          }
        }
      });
    }

    // Render districts page
    function renderDistrictsPage() {
      const container = document.getElementById('districts-container');
      const monthFilter = document.getElementById('districts-month-filter').value;
      const filteredRecords = getFilteredRecords(monthFilter, 'all');

      if (DISTRICTS.length === 0) {
        container.innerHTML = `
          <div class="empty-state">
            <div class="empty-state-icon">📊</div>
            <div class="empty-state-title">ไม่มีข้อมูลอำเภอ</div>
            <div class="empty-state-text">กำลังโหลดข้อมูล...</div>
          </div>
        `;
        return;
      }

      container.innerHTML = DISTRICTS.map(district => {
        const data = getDistrictData(district.id, filteredRecords);
        const ratingClass = `rating-badge-${data.rating.toLowerCase()}`;

        const jpthStatusClass = data.jpth_status === 'reported' ? 'status-success' : 'status-danger';
        const jpthStatusText = data.jpth_status === 'reported' ? 
          (data.jpth_ontime ? '✓ รายงานแล้ว (ตรงเวลา)' : '✓ รายงานแล้ว (เกินเวลา)') : 
          '✗ ยังไม่รายงาน';

        const issueStatusClass = data.issue_status === 'reported' ? 'status-success' : 'status-danger';
        const issueStatusText = data.issue_status === 'reported' ? 
          (data.issue_ontime ? '✓ ��ายงานแล้ว (ตรงเวลา)' : '✓ รายงานแล้ว (เกินเวลา)') : 
          '✗ ยังไม่รายงาน';

        return `
          <div class="district-card">
            <div class="district-card-header">
              <div class="district-name">${district.name}</div>
              <div class="rating-badge ${ratingClass}">${data.rating}</div>
            </div>
            <div class="district-status-list">
              <div class="district-status-item">
                <span class="district-status-label">จปฐ.</span>
                <span class="status-badge ${jpthStatusClass}">${jpthStatusText}</span>
              </div>
              <div class="district-status-item">
                <span class="district-status-label">ประเด็น 5+1</span>
                <span class="status-badge ${issueStatusClass}">${issueStatusText}</span>
              </div>
            </div>
          </div>
        `;
      }).join('');
    }

    // Render database table
    function renderDatabaseTable() {
      const tbody = document.getElementById('database-tbody');
      const monthFilter = document.getElementById('db-month-filter').value;
      const districtFilter = document.getElementById('db-district-filter').value;
      const filteredRecords = getFilteredRecords(monthFilter, districtFilter);

      if (filteredRecords.length === 0) {
        tbody.innerHTML = `
          <tr>
            <td colspan="7" style="text-align: center; padding: 2rem; color: #94a3b8;">
              <div style="font-size: 3rem; margin-bottom: 1rem;">📊</div>
              <div style="font-size: 1.125rem; font-weight: 600; margin-bottom: 0.5rem;">ไม่พบข้อมูลตามเงื่อนไขที่เลือก</div>
              <div style="font-size: 0.9375rem;">ลองเปลี่ยนตัวกรองหรือเพิ่มข้อมูลใหม่</div>
            </td>
          </tr>
        `;
        return;
      }

      // Get latest record for each district in filtered data
      const districtsToShow = districtFilter === 'all' ? DISTRICTS : DISTRICTS.filter(d => d.id === districtFilter);
      const latestRecords = districtsToShow.map(district => {
        const records = filteredRecords.filter(r => r.district_id === district.id);
        if (records.length === 0) return null;
        const latest = records[records.length - 1];
        return { ...latest, district_name: district.name };
      }).filter(r => r !== null);

      if (latestRecords.length === 0) {
        tbody.innerHTML = `
          <tr>
            <td colspan="7" style="text-align: center; padding: 2rem; color: #94a3b8;">
              <div style="font-size: 3rem; margin-bottom: 1rem;">📊</div>
              <div style="font-size: 1.125rem; font-weight: 600; margin-bottom: 0.5rem;">ไม่พบข้อมูลตามเงื่อนไขที่เลือก</div>
              <div style="font-size: 0.9375rem;">ลองเปลี่ยนตัวกรองหรือเพิ่มข้อมูลใหม่</div>
            </td>
          </tr>
        `;
        return;
      }

      tbody.innerHTML = latestRecords.map(record => {
        const data = getDistrictData(record.district_id, filteredRecords);
        const ratingClass = `rating-badge-${data.rating.toLowerCase()}`;

        const jpthStatusClass = record.jpth_status === 'reported' ? 'status-success' : 'status-danger';
        const jpthStatusText = record.jpth_status === 'reported' ? 'รายงานแล้ว' : 'ยังไม่รายงาน';

        const issueStatusClass = record.issue_5plus1_status === 'reported' ? 'status-success' : 'status-danger';
        const issueStatusText = record.issue_5plus1_status === 'reported' ? 'รายงานแล้ว' : 'ยังไม่รายงาน';

        const jpthDate = record.jpth_timestamp ? 
          new Date(record.jpth_timestamp).toLocaleDateString('th-TH', {
            year: 'numeric',
            month: 'short',
            day: 'numeric'
          }) : '-';

        const issueDate = record.issue_5plus1_timestamp ? 
          new Date(record.issue_5plus1_timestamp).toLocaleDateString('th-TH', {
            year: 'numeric',
            month: 'short',
            day: 'numeric'
          }) : '-';

        return `
          <tr>
            <td style="font-weight: 600;">${record.district_name}</td>
            <td><span class="status-badge ${jpthStatusClass}">${jpthStatusText}</span></td>
            <td>${jpthDate}</td>
            <td><span class="status-badge ${issueStatusClass}">${issueStatusText}</span></td>
            <td>${issueDate}</td>
            <td>${record.month || '-'}</td>
            <td><div class="rating-badge ${ratingClass}">${data.rating}</div></td>
          </tr>
        `;
      }).join('');
    }

    // Update all visualizations
    function updateDashboard(records = allRecords, monthFilter = 'all', districtFilter = 'all') {
      updateSummaryCards(records, districtFilter);
      updateDistrictChart(records, districtFilter);
      updateMonthlyChart(records);
      renderDistrictsPage();
      renderDatabaseTable();
    }

    // Data handler
    const dataHandler = {
      onDataChanged(data) {
        allRecords = data;
        updateFilterDropdowns();
        applyFilters();
      }
    };

    // Element SDK implementation
    async function onConfigChange(config) {
      const mainTitle = document.getElementById('main-title');
      const subtitle = document.getElementById('subtitle');
      const dashboardTitle = document.getElementById('dashboard-title');
      const districtsTitle = document.getElementById('districts-title');
      const databaseTitle = document.getElementById('database-title');
      const jpthFormLink = document.getElementById('jpth-form-link');
      const issueFormLink = document.getElementById('issue-form-link');

      if (mainTitle) mainTitle.textContent = config.main_title || defaultConfig.main_title;
      if (subtitle) subtitle.textContent = config.subtitle || defaultConfig.subtitle;
      if (dashboardTitle) dashboardTitle.textContent = config.dashboard_title || defaultConfig.dashboard_title;
      if (districtsTitle) districtsTitle.textContent = config.districts_title || defaultConfig.districts_title;
      if (databaseTitle) databaseTitle.textContent = config.database_title || defaultConfig.database_title;
      if (jpthFormLink) jpthFormLink.href = config.jpth_form_url || defaultConfig.jpth_form_url;
      if (issueFormLink) issueFormLink.href = config.issue_form_url || defaultConfig.issue_form_url;
    }

    function mapToCapabilities(config) {
      return {
        recolorables: [],
        borderables: [],
        fontEditable: undefined,
        fontSizeable: undefined
      };
    }

