  const submitDate = new Date(timestamp);
  const targetMonthIndex = MONTH_MAP[monthName];

  if (targetMonthIndex === undefined) return false;

  const submitYear = submitDate.getFullYear();
  const submitMonth = submitDate.getMonth();

  // Determine the target year for the deadline
  let targetYear = submitYear;

  // Handle year boundary: 
  // If reporting for December (11) but submitted in January (0), the target year was the previous year.
  if (targetMonthIndex === 11 && submitMonth === 0) {
    targetYear = submitYear - 1;
  } else if (targetMonthIndex > submitMonth && (targetMonthIndex - submitMonth > 6)) {
      // General case: If report month is much later in year than submit month (e.g. Report Nov, Submit Jan),
      // it means report is for previous year.
      targetYear = submitYear - 1;
  }

  // Create deadline: 15th of the target month at end of day
  const deadline = new Date(targetYear, targetMonthIndex, 15, 23, 59, 59);

  return submitDate <= deadline;
};

export const calculateRating = (
  jpthStatus: ReportingStatus,
  jpthOntime: boolean,
  issueStatus: ReportingStatus,
  issueOntime: boolean
): 'A' | 'B' | 'C' | 'D' => {
  const jpthReported = jpthStatus === 'reported';
  const issueReported = issueStatus === 'reported';

  if (jpthReported && issueReported && jpthOntime && issueOntime) {
    return 'A';
  } else if ((jpthReported && jpthOntime) || (issueReported && issueOntime)) {
    return 'B';
  } else if (jpthReported && issueReported) {
    return 'C';
  } else {
    return 'D';
  }
};

export const getDistrictSummary = (record: ReportRecord): DistrictSummary => {
  const jpthOntime = isOnTime(record.jpth_timestamp, record.month);
  const issueOntime = isOnTime(record.issue_5plus1_timestamp, record.month);

  return {
    district_id: record.district_id,
    district_name: record.district_name,
    month: record.month,
    jpth_status: record.jpth_status,
    jpth_ontime: jpthOntime,
    issue_status: record.issue_5plus1_status,
    issue_ontime: issueOntime,
    rating: calculateRating(record.jpth_status, jpthOntime, record.issue_5plus1_status, issueOntime)
  };
};

export const filterRecords = (records: ReportRecord[], month: string, districtId: string): ReportRecord[] => {
  return records.filter(r => {
    const matchMonth = month === 'all' || r.month === month;
    const matchDistrict = districtId === 'all' || r.district_id === districtId;
    return matchMonth && matchDistrict;
  });
};

// --- DATA FETCHING ---

async function fetchCSV(sheetId: string): Promise<string[][]> {
  const url = `https://docs.google.com/spreadsheets/d/${sheetId}/export?format=csv`;
  const corsUrl = `${CORS_PROXY}${encodeURIComponent(url)}`;

  try {
    // Add cache: no-store to prevent stale data
    const response = await fetch(corsUrl, { 
      cache: 'no-store',
      headers: {
        'Pragma': 'no-cache',
        'Cache-Control': 'no-cache'
      }
    });
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
    const text = await response.text();
    return parseCSV(text);
  } catch (error) {
    console.error(`Error fetching sheet ${sheetId}:`, error);
    return [];
  }
}

function parseCSV(text: string): string[][] {
  const rows: string[][] = [];
  let currentRow: string[] = [];
  let currentField = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const nextChar = text[i+1];

    if (inQuotes) {
      if (char === '"' && nextChar === '"') {
        currentField += '"';
        i++;
      } else if (char === '"') {
        inQuotes = false;
      } else {
        currentField += char;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
      } else if (char === ',') {
        currentRow.push(currentField);
        currentField = '';
      } else if (char === '\n' || char === '\r') {
        currentRow.push(currentField);
        currentField = '';
        rows.push(currentRow);
        currentRow = [];
        if (char === '\r' && nextChar === '\n') i++;
      } else {
        currentField += char;
      }
    }
  }
  if (currentField || currentRow.length > 0) {
    currentRow.push(currentField);
    rows.push(currentRow);
  }
  return rows;
}

interface SheetEntry {
  timestamp: string;
  districtId: string;
  month: string;
}

function processSheetData(rows: string[][]): SheetEntry[] {
  if (rows.length < 2) return [];

  const headers = rows[0].map(h => h.trim());

  // Identify columns
  // Keywords: "Timestamp"/"ประทับเวลา", "อำเภอ"/"District", "เดือน"/"Month"
  const timestampIdx = headers.findIndex(h => h.includes('Timestamp') || h.includes('ประทับเวลา') || h.includes('เวลา'));
  const districtIdx = headers.findIndex(h => h.includes('อำเภอ') || h.includes('District'));
  const monthIdx = headers.findIndex(h => h.includes('เดือน') || h.includes('Month'));

  if (timestampIdx === -1) return [];

  const entries: SheetEntry[] = [];

  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    const timestampStr = row[timestampIdx];
    if (!timestampStr) continue;

    // Parse Timestamp
    let timestamp = new Date(timestampStr).toISOString();
    if (timestamp === 'Invalid Date') {
      continue; 
    }

    // Find District
    let districtId = '';
    const rawDistrict = districtIdx !== -1 ? row[districtIdx] : '';
    const matchedDistrict = DISTRICTS.find(d => rawDistrict.includes(d.name));
    if (matchedDistrict) {
      districtId = matchedDistrict.id;
    } else {
      continue; 
    }

    // Find Month
    let month = '';
    if (monthIdx !== -1 && row[monthIdx]) {
      const rawMonth = row[monthIdx].trim();
      const foundMonth = MONTHS.find(m => rawMonth.includes(m));
      if (foundMonth) month = foundMonth;
    } 

    if (!month) {
      const date = new Date(timestamp);
      month = MONTHS[date.getMonth()];
    }

    entries.push({ timestamp, districtId, month });
  }
  return entries;
}

export const fetchData = async (): Promise<ReportRecord[]> => {
  // Parallel fetch
  const [jpthRaw, issueRaw] = await Promise.all([
    fetchCSV(JPTH_SHEET_ID),
    fetchCSV(ISSUE_SHEET_ID)
  ]);

  const jpthEntries = processSheetData(jpthRaw);
  const issueEntries = processSheetData(issueRaw);

  const records: ReportRecord[] = [];

  MONTHS.forEach(month => {
    DISTRICTS.forEach(district => {
      // Find latest JPTH entry for this district+month
      const jpthEntry = jpthEntries
        .filter(e => e.districtId === district.id && e.month === month)
        .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())[0];

      // Find latest Issue entry
      const issueEntry = issueEntries
        .filter(e => e.districtId === district.id && e.month === month)
        .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())[0];

      records.push({
        id: `${district.id}-${month}`,
        district_id: district.id,
        district_name: district.name,
        month: month,
        jpth_status: jpthEntry ? 'reported' : 'not_reported',
        jpth_timestamp: jpthEntry ? jpthEntry.timestamp : null,
        issue_5plus1_status: issueEntry ? 'reported' : 'not_reported',
        issue_5plus1_timestamp: issueEntry ? issueEntry.timestamp : null,
      });
    });
  });

  return records;
};

